//! Bridge onto the one process [`knowledge_core::admission::Account`].
//!
//! This module does not start that account, mint a source digest, or keep a
//! second pool. Callers reserve on [`Account::current`] before an effect.
//! Memory reservations cover live allocations only. Generated files use
//! `temporary_bytes`. [`Holding`] does not release on drop; finish a working
//! buffer or a settled child explicitly, and return the holding for text that
//! stays live.

use std::fmt;

/// Serialize native unit-test account observations; production has no adapter queue or lock.
#[cfg(test)]
pub(crate) static TEST_GATE: std::sync::Mutex<()> = std::sync::Mutex::new(());

use knowledge_core::admission::{Account, Decision, Error, Holding, Origin, Waiting};
use knowledge_core::jobs::Reservation;

/// One effect cost. Only live memory and generated storage become reservations.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Charge {
    /// Bytes about to be read. This is not a permanent memory charge.
    Input { bytes: u64 },
    /// Parser or decompression allocation that dies before return.
    Work { bytes: u64 },
    /// Derived text that stays live after return.
    Output { bytes: u64 },
    /// Child or retained transcript cost while that resource stays live.
    Live { bytes: u64 },
    /// Generated bytes about to be written.
    Storage { bytes: u64 },
}

impl Charge {
    /// Byte count carried by this charge.
    pub fn bytes(self) -> u64 {
        match self {
            Self::Input { bytes }
            | Self::Work { bytes }
            | Self::Output { bytes }
            | Self::Live { bytes }
            | Self::Storage { bytes } => bytes,
        }
    }

    /// Generated-storage charges use the account's temporary-byte promise.
    pub fn is_storage(self) -> bool {
        matches!(self, Self::Storage { .. })
    }
}

/// Map one charge onto the existing jobs reservation.
///
/// Storage is temporary bytes. Every other charge is memory, and the caller
/// finishes work and input holdings when those buffers die.
pub fn reservation(charge: Charge) -> Reservation {
    if charge.is_storage() {
        Reservation {
            memory_bytes: 0,
            temporary_bytes: charge.bytes(),
        }
    } else {
        Reservation {
            memory_bytes: charge.bytes(),
            temporary_bytes: 0,
        }
    }
}

/// Value plus the holdings that still cover its live bytes.
///
/// Dropping `retained` does not release those charges. The owner finishes each
/// holding when the corresponding bytes are gone.
pub struct Admitted<T> {
    /// Admitted result.
    pub value: T,
    /// Live-memory holdings for bytes still owned by `value`.
    pub retained: Vec<Holding>,
}

/// Refusal from the shared account. Processing does not retry or spin.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AdmitError {
    /// No process account has been started.
    NotStarted,
    /// The account belongs to another process.
    WrongProcess,
    /// The need exceeds the whole memory ceiling.
    TooLargeMemory,
    /// The need exceeds the whole generated-storage ceiling.
    TooLargeStorage,
    /// Current memory promises block this charge.
    WaitingMemory,
    /// Current storage promises block this charge.
    WaitingStorage,
    /// Shared holding records are full.
    Records,
    /// The holding was already finished or is not from this account.
    Stale,
    /// The supplied claim has less remaining credit than this complete call needs.
    InsufficientCredit,
    /// Another typed account refusal.
    Account,
}

impl fmt::Display for AdmitError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        let text = match self {
            Self::NotStarted => "processing admission: account is not started",
            Self::WrongProcess => "processing admission: account belongs to another process",
            Self::TooLargeMemory => "processing admission: memory need exceeds the shared account",
            Self::TooLargeStorage => {
                "processing admission: storage need exceeds the shared account"
            }
            Self::WaitingMemory => "processing admission: waiting for memory",
            Self::WaitingStorage => "processing admission: waiting for storage",
            Self::Records => "processing admission: holding records are full",
            Self::Stale => "processing admission: holding is stale",
            Self::InsufficientCredit => "processing admission: insufficient funded claim credit",
            Self::Account => "processing admission: account refused the charge",
        };
        formatter.write_str(text)
    }
}

impl std::error::Error for AdmitError {}

/// The process account. Fails before any processing effect when it is absent.
pub fn current() -> Result<&'static Account, AdmitError> {
    Account::current().map_err(map_error)
}

/// Reserve live memory before the allocation it covers.
pub fn reserve_memory(bytes: u64) -> Result<Holding, AdmitError> {
    reserve(Reservation {
        memory_bytes: bytes,
        temporary_bytes: 0,
    })
}

/// Reserve generated storage before creating or extending the file.
pub fn reserve_storage(bytes: u64) -> Result<Holding, AdmitError> {
    reserve(Reservation {
        memory_bytes: 0,
        temporary_bytes: bytes,
    })
}

/// Spendable memory after current promises.
pub fn available_memory() -> Result<u64, AdmitError> {
    Ok(current()?.status().map_err(map_error)?.memory_available)
}

/// Spendable generated storage after the floor and current promises.
pub fn available_storage() -> Result<u64, AdmitError> {
    Ok(current()?.status().map_err(map_error)?.storage_available)
}

/// Record bytes just written, then the caller finishes any unused promise.
pub fn note_written(holding: &mut Holding, bytes: u64) -> Result<(), AdmitError> {
    holding.written(bytes).map(|_| ()).map_err(map_error)
}

/// Release this holding after the resource it covered is gone.
pub fn release(holding: &mut Holding) -> Result<(), AdmitError> {
    holding.finish().map_err(map_error)
}

fn reserve(need: Reservation) -> Result<Holding, AdmitError> {
    if need.memory_bytes == 0 && need.temporary_bytes == 0 {
        return Err(AdmitError::TooLargeMemory);
    }
    match current()?
        .reserve(need, Origin::BeforeVerification)
        .map_err(map_error)?
    {
        Decision::Ready(holding) => Ok(holding),
        Decision::Waiting(Waiting::Memory) => Err(AdmitError::WaitingMemory),
        Decision::Waiting(Waiting::Storage) => Err(AdmitError::WaitingStorage),
    }
}

/// Start the one process account for a test or a host harness.
///
/// Production adapters do not call this. The process owner calls
/// [`Account::start`] with the directory it already admitted. A second call
/// is success when that account is already the current one.
pub fn establish_process_account() -> Result<(), AdmitError> {
    use std::sync::OnceLock;
    static STARTED: OnceLock<Result<(), AdmitError>> = OnceLock::new();
    *STARTED.get_or_init(|| {
        #[cfg(unix)]
        {
            use std::fs::File;
            use std::os::unix::fs::PermissionsExt;
            let path = tempfile::tempdir().map_err(|_| AdmitError::Account)?.keep();
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o700))
                .map_err(|_| AdmitError::Account)?;
            let directory = File::open(&path).map_err(|_| AdmitError::Account)?;
            match Account::start(
                directory,
                knowledge_core::admission::Configuration {
                    memory_bytes: None,
                    storage_bytes: None,
                },
                knowledge_core::admission::Scheduling {
                    max_pending: 64,
                    max_records: 4096,
                    max_descriptor_bytes: 1 << 20,
                    per_mount: 4,
                },
            ) {
                Ok(_) => Ok(()),
                Err(Error::AlreadyStarted) => Ok(()),
                Err(error) => Err(map_error(error)),
            }
        }
        #[cfg(not(unix))]
        {
            Err(AdmitError::Account)
        }
    })
}

pub(crate) fn map_error(error: Error) -> AdmitError {
    match error {
        Error::NotStarted => AdmitError::NotStarted,
        Error::WrongProcess => AdmitError::WrongProcess,
        Error::TooLargeMemory => AdmitError::TooLargeMemory,
        Error::TooLargeStorage => AdmitError::TooLargeStorage,
        Error::Records => AdmitError::Records,
        Error::Stale => AdmitError::Stale,
        _ => AdmitError::Account,
    }
}

/// Releases a working or child holding when dropped, after the caller has
/// settled the resource. Do not use this for text that is returned live.
pub(crate) struct Settled(pub Option<Holding>);

impl Settled {
    pub(crate) fn written(&mut self, bytes: u64) -> Result<(), AdmitError> {
        if bytes == 0 {
            return Ok(());
        }
        let holding = self.0.as_mut().ok_or(AdmitError::Stale)?;
        note_written(holding, bytes)
    }

    pub(crate) fn release_now(&mut self) -> Result<(), AdmitError> {
        if let Some(mut holding) = self.0.take() {
            release(&mut holding)?;
        }
        Ok(())
    }
}

impl Drop for Settled {
    fn drop(&mut self) {
        if let Some(mut holding) = self.0.take() {
            let _ = release(&mut holding);
        }
    }
}
